<script>
(() => {
  "use strict";

  // ---------- Constants ----------
  const GRID = 30;
  const CELL = 20;               // internal cell size in px (canvas 600x600)
  const TICK_MS = 110;           // game speed
  const DIRS = {
    up:    { x: 0, y: -1 },
    down:  { x: 0, y: 1 },
    left:  { x: -1, y: 0 },
    right: { x: 1, y: 0 },
