  // ---------- DOM ----------
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const menuEl = document.getElementById("menu");
  const gameoverEl = document.getElementById("gameover");
  const p1ScoreEl = document.getElementById("p1-score");
  const p2ScoreEl = document.getElementById("p2-score");
  const p1LabelEl = document.getElementById("p1-label");
  const p2LabelEl = document.getElementById("p2-label");
  const modeTagEl = document.getElementById("mode-tag");
  const winnerTextEl = document.getElementById("winner-text");
  const finalScoreEl = document.getElementById("final-score");
  const gameoverSubEl = document.getElementById("gameover-sub");

  // ---------- State ----------
  let state = "menu";            // menu | playing | gameover
  let mode = null;
  let snakes = [];               // [{body:[{x,y}], dir, nextDir, score, alive, color, isCpu}]
  let food = { x: 0, y: 0 };
  let accumulator = 0;
  let lastTime = 0;
  let pendingGameOver = null;    // { winnerIndex, reason }

