  function spawnFood() {
    const occupied = new Set();
    snakes.forEach(s => s.body.forEach(seg => occupied.add(key(seg.x, seg.y))));
    const free = [];
    for (let y = 0; y < GRID; y++) {
      for (let x = 0; x < GRID; x++) {
        if (!occupied.has(key(x, y))) free.push({ x, y });
      }
    }
    if (free.length === 0) { endGame({ winnerIndex: -1, reason: "Board full — draw!" }); return; }
    food = free[randInt(free.length)];
  }

