    // P1 starts on the left, P2 on the right
    const startX = index === 0 ? 6 : GRID - 7;
    const startY = Math.floor(GRID / 2);
    const body = [];
    for (let i = 0; i < 4; i++) {
      body.push({ x: startX - (index === 0 ? i : -i), y: startY });
    }
    return {
      body,
      dir: index === 0 ? "right" : "left",
      nextDir: index === 0 ? "right" : "left",
      score: 0,
      alive: true,
      color,
      isCpu,
      grow: 0,
    };
  }

  function startGame(selectedMode) {
    mode = MODES[selectedMode];
    if (!mode) return;
    snakes = [
      resetSnake(0, "#4ade80", mode.p1 === "cpu"),
      resetSnake(1, "#60a5fa", mode.p2 === "cpu"),
    ];
