    snakes[1].body = [{x:GRID-7,y:15},{x:GRID-6,y:15},{x:GRID-5,y:15},{x:GRID-4,y:15}];
    p1LabelEl.textContent = mode.p1 === "cpu" ? "CPU 1" : "P1";
    p2LabelEl.textContent = mode.p2 === "cpu" ? "CPU 2" : "P2";
    p1ScoreEl.textContent = "0";
    p2ScoreEl.textContent = "0";
    modeTagEl.textContent = mode.name;
    spawnFood();
    pendingGameOver = null;
    accumulator = 0;
    state = "playing";
    menuEl.classList.add("hidden");
    gameoverEl.classList.add("hidden");
  }

  function endGame(result) {
    if (state === "gameover") return;
    pendingGameOver = result;
    state = "gameover";

    const s1 = snakes[0] ? snakes[0].score : 0;
    const s2 = snakes[1] ? snakes[1].score : 0;
    let winner = "";
    if (result.winnerIndex === -1) {
      winner = "Draw";
    } else if (result.winnerIndex === 0) {
      winner = mode.p1 === "cpu" ? "CPU 1 Wins!" : "Player 1 Wins!";
    } else {
      winner = mode.p2 === "cpu" ? "CPU 2 Wins!" : "Player 2 Wins!";
    }
    winnerTextEl.textContent = winner;
    finalScoreEl.innerHTML = `P1: <span>${s1}</span> &nbsp;·&nbsp; P2: <span>${s2}</span>`;
    gameoverSubEl.textContent = result.reason || "";
    gameoverEl.classList.remove("hidden");
  }

  function showMenu() {
    state = "menu";
    mode = null;
    pendingGameOver = null;
    menuEl.classList.remove("hidden");
    gameoverEl.classList.add("hidden");
    modeTagEl.textContent = "Menu";
    p1ScoreEl.textContent = "0";
    p2ScoreEl.textContent = "0";
    p1LabelEl.textContent = "P1";
    p2LabelEl.textContent = "P2";
    // draw a static backdrop
    snakes = [resetSnake(0, "#4ade80", false), resetSnake(1, "#60a5fa", false)];
    snakes[0].body = [{x:6,y:15},{x:5,y:15},{x:4,y:15},{x:3,y:15}];
    snakes[1].body = [{x:GRID-7,y:15},{x:GRID-6,y:15},{x:GRID-5,y:15},{x:GRID-4,y:15}];
    food = { x: 15, y: 15 };
    draw();
  }

  // ---------- CPU AI (BFS shortest path to food with safety check) ----------
  function bfsPath(start, goal, blockedSet) {
    const startK = key(start.x, start.y);
    const goalK = key(goal.x, goal.y);
    if (startK === goalK) return [];
    const prev = new Map();
    prev.set(startK, null);
    const queue = [start];
    let qi = 0;
    while (qi < queue.length) {
      const cur = queue[qi++];
      for (const dName of ["up", "down", "left", "right"]) {
        const d = DIRS[dName];
        const nx = cur.x + d.x, ny = cur.y + d.y;
        if (nx < 0 || ny < 0 || nx >= GRID || ny >= GRID) continue;
        const nk = key(nx, ny);
        if (prev.has(nk)) continue;
        if (blockedSet.has(nk) && nk !== goalK) continue;
        prev.set(nk, cur);
        if (nk === goalK) {
          // reconstruct
          const path = [];
          let node = { x: nx, y: ny };
          while (node && key(node.x, node.y) !== startK) {
            path.unshift(node);
            node = prev.get(key(node.x, node.y));
          }
          return path;
        }
        queue.push({ x: nx, y: ny });
      }
    }
    return null; // no path
  }

  function cellFreeFor(snake, x, y) {
    if (x < 0 || y < 0 || x >= GRID || y >= GRID) return false;
    const k = key(x, y);
    // other snakes' bodies block (their tails may move away, but be conservative for heads)
    for (const other of snakes) {
      const len = other.body.length;
      for (let i = 0; i < len; i++) {
        // allow following into a tail cell that will move (unless growing)
        const isTail = i === len - 1;
        if (isTail && other.grow === 0 && other !== snake) continue;
        if (isTail && other.grow === 0 && other === snake) continue;
        if (key(other.body[i].x, other.body[i].y) === k) return false;
      }
    }
    return true;
  }

  function cpuChooseDir(snake) {
    const head = snake.body[0];

    // Build blocked set: walls are implicit; blocks = all snake bodies except target food
    const blocked = new Set();
    for (const s of snakes) {
      const len = s.body.length;
      for (let i = 0; i < len; i++) {
        const isTail = i === len - 1 && s.grow === 0;
        if (isTail) continue; // tail will move away
        blocked.add(key(s.body[i].x, s.body[i].y));
      }
    }
    // head itself is fine
    blocked.delete(key(head.x, head.y));

    const path = bfsPath(head, food, blocked);

    let candidate = null;
    if (path && path.length > 0) {
      candidate = dirBetween(head, path[0]);
    }

    // Evaluate candidate: simulate one step and check we still have room to live
    const options = [];
    for (const dName of ["up", "down", "left", "right"]) {
      if (dName === OPPOSITE[snake.dir]) continue; // no reversing
      const d = DIRS[dName];
      const nx = head.x + d.x, ny = head.y + d.y;
      if (nx < 0 || ny < 0 || nx >= GRID || ny >= GRID) continue;
      if (!cellFreeFor(snake, nx, ny)) continue;
      options.push(dName);
    }
    if (options.length === 0) {
      // forced move — pick anything legal (probably death)
      for (const dName of ["up", "down", "left", "right"]) {
        if (dName === OPPOSITE[snake.dir]) continue;
        const d = DIRS[dName];
        const nx = head.x + d.x, ny = head.y + d.y;
        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID) return dName;
      }
      return snake.dir;
    }

    // Prefer the BFS candidate if it's legal
    if (candidate && options.includes(candidate)) {
      // Safety: check that after moving, we can still reach some free space (flood fill)
      const d = DIRS[candidate];
      const nx = head.x + d.x, ny = head.y + d.y;
      if (floodFillSize({ x: nx, y: ny }, snake) >= Math.min(snake.body.length + 2, 12)) {
        return candidate;
      }
    }

    // Fallback: choose the option with the most free space around the target cell
    let best = options[0];
    let bestScore = -Infinity;
    for (const dName of options) {
      const d = DIRS[dName];
      const nx = head.x + d.x, ny = head.y + d.y;
      const space = floodFillSize({ x: nx, y: ny }, snake);
      let score = space;
      if (dName === snake.dir) score += 1; // slight preference to keep moving
      if (space > bestScore) { bestScore = space; best = dName; }
    }
    return best;
  }

  function dirBetween(a, b) {
    if (b.x > a.x) return "right";
    if (b.x < a.x) return "left";
    if (b.y > a.y) return "down";
    if (b.y < a.y) return "up";
    return null;
  }

  function floodFillSize(start, snake) {
    const blocked = new Set();
    for (const s of snakes) {
      const len = s.body.length;
      for (let i = 0; i < len; i++) {
        const isTail = i === len - 1 && s.grow === 0;
        if (isTail) continue;
        blocked.add(key(s.body[i].x, s.body[i].y));
      }
    }
    blocked.delete(key(start.x, start.y));
    const seen = new Set([key(start.x, start.y)]);
    const queue = [start];
    let qi = 0;
    let count = 0;
    while (qi < queue.length) {
      const cur = queue[qi++];
      count++;
      for (const d of Object.values(DIRS)) {
        const nx = cur.x + d.x, ny = cur.y + d.y;
        if (nx < 0 || ny < 0 || nx >= GRID || ny >= GRID) continue;
        const nk = key(nx, ny);
        if (seen.has(nk) || blocked.has(nk)) continue;
        seen.add(nk);
        queue.push({ x: nx, y: ny });
      }
    }
    return count;
  }

  // ---------- Input ----------
  const KEYMAP_P1 = {
    w: "up", a: "left", s: "down", d: "right",
  };
  const KEYMAP_P2 = {
    ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right",
  };

  document.addEventListener("keydown", (e) => {
    const k = e.key;

    if (state === "menu") {
      if (k === "1") { startGame("hvh"); e.preventDefault(); return; }
      if (k === "2") { startGame("cvh"); e.preventDefault(); return; }
      if (k === "3") { startGame("cvc"); e.preventDefault(); return; }
      return;
    }

    if (state === "gameover") {
      if (k === "r" || k === "R" || k === "Enter") {
        // restart same mode
        if (mode) {
          const modeKey = Object.keys(MODES).find(mk => MODES[mk] === mode);
          startGame(modeKey);
        }
        e.preventDefault();
        return;
      }
      if (k === "Escape") { showMenu(); e.preventDefault(); return; }
      return;
    }

    if (state === "playing") {
      if (k === "Escape") { showMenu(); e.preventDefault(); return; }
      if (k === "r" || k === "R") {
        const modeKey = Object.keys(MODES).find(mk => MODES[mk] === mode);
        startGame(modeKey);
        e.preventDefault();
        return;
      }

      // P1: WASD (only if P1 is human)
      const lower = k.length === 1 ? k.toLowerCase() : k;
      if (KEYMAP_P1[lower] && !snakes[0].isCpu) {
