      if (KEYMAP_P2[k] && !snakes[1].isCpu) {
        const d = KEYMAP_P2[k];
        if (d !== OPPOSITE[snakes[1].dir]) snakes[1].nextDir = d;
        e.preventDefault();
        return;
      }
    }
  });

  // Menu buttons
  document.querySelectorAll(".mode-btn").forEach(btn => {
    btn.addEventListener("click", () => startGame(btn.dataset.mode));
  });

  // ---------- Game Logic ----------
  function step() {
    // 1. Compute CPU decisions first
    for (const s of snakes) {
      if (s.isCpu && s.alive) {
        s.nextDir = cpuChooseDir(s);
      }
    }

    // 2. Apply directions
    for (const s of snakes) {
      if (!s.alive) continue;
      if (s.nextDir !== OPPOSITE[s.dir]) s.dir = s.nextDir;
    }

    // 3. Compute new heads
    const newHeads = snakes.map(s => {
      if (!s.alive) return null;
      const d = DIRS[s.dir];
      return { x: s.body[0].x + d.x, y: s.body[0].y + d.y };
    });

    // 4. Wall collisions
    for (let i = 0; i < snakes.length; i++) {
      const s = snakes[i];
      if (!s.alive) continue;
      const h = newHeads[i];
      if (h.x < 0 || h.y < 0 || h.x >= GRID || h.y >= GRID) {
        s.alive = false;
      }
    }

    // 5. Self / other-snake body collisions (excluding tails that will move)
    for (let i = 0; i < snakes.length; i++) {
      const s = snakes[i];
      if (!s.alive) continue;
      const h = newHeads[i];
      for (let j = 0; j < snakes.length; j++) {
        const other = snakes[j];
        if (!other.alive) continue;
        const len = other.body.length;
        for (let seg = 0; seg < len; seg++) {
          const isTail = seg === len - 1 && other.grow === 0;
          if (isTail) continue;
          // skip own head position (it's moving)
          if (j === i && seg === 0) continue;
          if (other.body[seg].x === h.x && other.body[seg].y === h.y) {
            s.alive = false;
            break;
          }
        }
        if (!s.alive) break;
      }
    }

    // 6. Head-to-head collision
    if (snakes[0].alive && snakes[1].alive &&
        newHeads[0].x === newHeads[1].x && newHeads[0].y === newHeads[1].y) {
      snakes[0].alive = false;
      snakes[1].alive = false;
    }

    // 7. Move bodies & eat food
    for (let i = 0; i < snakes.length; i++) {
      const s = snakes[i];
      if (!s.alive) continue;
      const h = newHeads[i];
      s.body.unshift(h);
      if (h.x === food.x && h.y === food.y) {
        s.score += 1;
        s.grow += 1;
        p1ScoreEl.textContent = snakes[0].score;
        p2ScoreEl.textContent = snakes[1].score;
      }
      if (s.grow > 0) {
        s.grow -= 1;
      } else {
        s.body.pop();
      }
    }

    // 8. Respawn food if eaten
    const ate = snakes.some(s => s.alive && s.body[0].x === food.x && s.body[0].y === food.y);
    if (ate) spawnFood();

    // 9. Determine game over
    const aliveCount = snakes.filter(s => s.alive).length;
    if (aliveCount === 0) {
      endGame({ winnerIndex: -1, reason: "Both snakes crashed!" });
    } else if (aliveCount === 1) {
      const winnerIndex = snakes[0].alive ? 0 : 1;
      const dead = snakes[1 - winnerIndex];
      endGame({ winnerIndex, reason: `${dead.isCpu ? "CPU" : "Player"} ${1 - winnerIndex + 1} hit a wall or itself.` });
    }
  }

  // ---------- Rendering ----------
  function draw() {
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    // grid
    ctx.strokeStyle = "rgba(255,255,255,0.04)";
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID; i++) {
      const p = i * CELL;
      ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, H); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(W, p); ctx.stroke();
    }

    // food
    if (food) {
      const fx = food.x * CELL, fy = food.y * CELL;
      const pad = 3;
      const pulse = 1 + Math.sin(performance.now() / 200) * 0.12;
      const size = (CELL - pad * 2) * pulse;
      const off = (CELL - size) / 2;
      ctx.fillStyle = "#f472b6";
      ctx.shadowColor = "#f472b6";
      ctx.shadowBlur = 14;
      roundRect(fx + off, fy + off, size, size, 5);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    // snakes
    snakes.forEach((s, idx) => {
      if (!s.alive && state === "playing") return;
      s.body.forEach((seg, i) => {
        const x = seg.x * CELL, y = seg.y * CELL;
        const isHead = i === 0;
        const alpha = s.alive ? 1 : 0.35;
        ctx.globalAlpha = alpha;
        ctx.fillStyle = isHead ? lighten(s.color, 30) : s.color;
        ctx.shadowColor = s.color;
        ctx.shadowBlur = isHead ? 14 : 6;
        const pad = isHead ? 1 : 2;
        roundRect(x + pad, y + pad, CELL - pad * 2, CELL - pad * 2, isHead ? 5 : 4);
        ctx.fill();
        ctx.shadowBlur = 0;
        ctx.globalAlpha = 1;

        // eyes on head
        if (isHead && s.alive) {
          drawEyes(seg, s.dir);
        }
      });
    });
  }

  function drawEyes(seg, dir) {
    const cx = seg.x * CELL + CELL / 2;
    const cy = seg.y * CELL + CELL / 2;
    const r = 2.4;
    let e1, e2;
    const off = 3.4;
    if (dir === "up")    { e1 = [cx - off, cy - 1]; e2 = [cx + off, cy - 1]; }
    else if (dir === "down")  { e1 = [cx - off, cy + 1]; e2 = [cx + off, cy + 1]; }
    else if (dir === "left")  { e1 = [cx - 1, cy - off]; e2 = [cx - 1, cy + off]; }
    else                  { e1 = [cx + 1, cy - off]; e2 = [cx + 1, cy + off]; }
    ctx.fillStyle = "#0b0f1a";
    ctx.beginPath(); ctx.arc(e1[0], e1[1], r, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(e2[0], e2[1], r, 0, Math.PI * 2); ctx.fill();
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function lighten(hex, amt) {
    const n = parseInt(hex.slice(1), 16);
    let r = (n >> 16) + amt;
    let g = ((n >> 8) & 0xff) + amt;
    let b = (n & 0xff) + amt;
    r = Math.min(255, r); g = Math.min(255, g); b = Math.min(255, b);
    return `rgb(${r},${g},${b})`;
  }

  // ---------- Main Loop ----------
  function loop(time) {
    if (!lastTime) lastTime = time;
    const dt = Math.min(time - lastTime, 250);
    lastTime = time;

    if (state === "playing") {
      accumulator += dt;
      while (accumulator >= TICK_MS) {
        accumulator -= TICK_MS;
        if (state === "playing") step();
      }
    }

    draw();
    requestAnimationFrame(loop);
  }

  // ---------- Boot ----------
  showMenu();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
